interface Policy { can(subject:string, action:string, resource:string): Promise<boolean>; }
class FineGrainedAccessor {
  constructor(private policy: Policy, private storage: Storage) {}
  async read(subject: string, resource: string) {
    if (!await this.policy.can(subject, 'read', resource))
      throw new Error('access denied');
    return this.storage.read(resource);
  }
}
